),
allw AS (SELECT ST_MakeValid(ST_Union(g)) AS g FROM parts),
city AS (SELECT ST_MakeValid(geometry) AS g FROM essentials.geofence_boundaries
          WHERE state='38' AND mtfcc='G4110' AND geo_id='3832060'),
gap AS (SELECT (ST_Dump(ST_Difference(c.g, a.g))).geom AS g FROM allw a, city c),
ext AS (SELECT (ST_Dump(ST_Difference(a.g, c.g))).geom AS g FROM allw a, city c)
SELECT 'city NOT in any ward' AS kind, count(*) AS pieces,
       round((sum(ST_Area(g::geography))/2589988.11)::numeric,4) AS total_sqmi,
       round((max(ST_Area(g::geography))/2589988.11)::numeric,4) AS largest_sqmi,
       round((max(ST_Area(g::geography)) filter (where true) / nullif(max(ST_Perimeter(g::geography)),0))::numeric,2) AS area_per_metre_of_edge
FROM gap WHERE ST_Area(g::geography) > 1
UNION ALL
SELECT 'ward OUTSIDE the city', count(*),
       round((sum(ST_Area(g::geography))/2589988.11)::numeric,4),
       round((max(ST_Area(g::geography))/2589988.11)::numeric,4),
       round((max(ST_Area(g::geography)) / nullif(max(ST_Perimeter(g::geography)),0))::numeric,2)
FROM ext WHERE ST_Area(g::geography) > 1;

